const r = await tools.ask_user_question({
  questions: [{
    id: "pick",
    header: "选哪个装",
    question: "最贴合你需求的是 dsh-grill-first（★3，正好是「开工前反复追问、确认后才放行」）。要装哪个？",
    options: [
      { label: "装 dsh-grill-first（推荐）", description: "轻量：每轮问 3 个问题、最多 3 轮，问清后给你一份四段清单确认，strict 模式下需求没确认前禁止改文件/跑命令。" },
      { label: "装 dsh-doublecheck（★57，重量级）", description: "整个工程纪律包：拷问需求 + TDD 红绿门 + 对抗评审 + 交付门禁。功能强但会改变整个开发流程，非代码任务会很吵。" },
      { label: "两个都装", description: "grill-first 负责开工前问清，doublecheck 负责实施中质量门禁，可能有重叠提示。" },
      { label: "先别装，我自己看看", description: "我只给你对比信息，不动你的 profile。" }
    ]
  }]
});
console.log(JSON.stringify(r));
